// Mengambil string jawaban mentah dari Groq
let rawText = $input.first().json.choices[0].message.content;

try {
    // Mengubah string JSON menjadi objek asli
    let finalData = JSON.parse(rawText);

    // Mencegah error Telegram dengan mengubah simbol * menjadi huruf x
    let teksAman = finalData.jawaban.replace(/\*/g, 'x');

    // Meneruskan HANYA teks jawabannya ke node selanjutnya
    return [{ json: { teks_balasan: teksAman } }];
} catch (e) {
    return [{ json: { teks_balasan: "Maaf, format balasan AI sedang gangguan." } }];
}
